<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { Search, Refresh } from '@element-plus/icons-vue'
import { authAndAdminApi, type ModelConfig, type AuditLog, type AuditQuery } from '@/api/authAndAdminApi'
import { formatTime } from '@/api/types'
const config = reactive<ModelConfig>({ activeProvider: 'MOCK_LOCAL', baseUrl: '', modelName: '', apiKeyPlain: '', apiKeyMasked: '', enableMockFallback: true, sensitiveWords: [] })
const configLoading = ref(false), configReady = ref(false), configError = ref(false), saving = ref(false), form = ref<FormInstance>(), words = ref('')
const rules: FormRules = {
  activeProvider: [{ required: true, message: '请选择模型通道' }],
  baseUrl: [{ required: true, message: '请输入 API 地址' }, { pattern: /^https?:\/\/[^\s?#@]+$/, message: '请输入合法的 HTTP(S) API 地址', trigger: 'blur' }],
  modelName: [{ required: true, whitespace: true, message: '请输入模型名称' }]
}
const rows = ref<AuditLog[]>([]), total = ref(0), loading = ref(false), failed = ref(false), dates = ref<[string, string] | null>(null), detail = ref<AuditLog>(), drawer = ref(false)
const query = reactive<AuditQuery>({ username: '', pageNum: 1, pageSize: 10 })
const modules = ['AUTH','WORKFLOW','ENGINE','EDU','ADMIN'], actions = ['LOGIN','LOGOUT','EXEC_AI','SENSITIVE_BLOCK','QUOTA_CHANGE','MODEL_CONFIG','USER_UPDATE','EXCEPTION'], providers = ['MOCK_LOCAL','DEEPSEEK','QWEN']
let requestId = 0
async function loadConfig() {
  configLoading.value = true; configError.value = false
  try { const result = await authAndAdminApi.modelConfig(); Object.assign(config, result, { apiKeyPlain: '' }); words.value = result.sensitiveWords.join('\n'); configReady.value = true }
  catch { configError.value = true } finally { configLoading.value = false }
}
async function saveConfig() {
  if (!configReady.value || !(await form.value?.validate().catch(() => false))) return
  const sensitiveWords = [...new Set(words.value.split('\n').map(w => w.trim()).filter(Boolean))]
  if (sensitiveWords.length > 200 || sensitiveWords.some(w => w.length > 100)) { ElMessage.warning('最多200条敏感词，每条不超过100个字符'); return }
  saving.value = true
  try {
    const result = await authAndAdminApi.updateModelConfig({ ...config, sensitiveWords })
    Object.assign(config, result, { apiKeyPlain: '' }); words.value = result.sensitiveWords.join('\n')
    ElMessage.success('模型通道与敏感词规则已保存'); await loadLogs(true)
  } catch { /* Request interceptor displays the server error. */ } finally { saving.value = false }
}
async function loadLogs(reset = false) {
  if (reset) query.pageNum = 1
  const id = ++requestId; loading.value = true; failed.value = false
  try { const page = await authAndAdminApi.auditLogs({ ...query, startTime: dates.value?.[0], endTime: dates.value?.[1] }); if (id === requestId) { rows.value = page.records; total.value = page.total } }
  catch { if (id === requestId) failed.value = true } finally { if (id === requestId) loading.value = false }
}
function reset() { Object.assign(query, { username: '', moduleName: undefined, actionType: undefined, modelProvider: undefined, httpStatus: undefined, pageNum: 1 }); dates.value = null; void loadLogs() }
function showDetail(row: AuditLog) { detail.value = row; drawer.value = true }
onMounted(() => { void loadConfig(); void loadLogs() })
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">MODEL GOVERNANCE</p><h1>模型与安全审计</h1><p class="subtitle">配置模型通道、维护敏感词规则，追踪平台安全与算力事件。</p></div></div><article v-loading="configLoading" class="panel config-panel"><div class="panel-heading"><div><h2>模型通道与安全规则</h2><p>未配置 Key 时可使用本地沙箱；留空 Key 保留已有配置。</p></div><el-button :icon="Refresh" :disabled="saving" @click="loadConfig">重新加载</el-button></div><el-alert v-if="configError" title="配置加载失败，请重新加载后再保存" type="error" :closable="false"/><el-form ref="form" :model="config" :rules="rules" label-position="top" :disabled="!configReady || configLoading || saving" @submit.prevent="saveConfig"><div class="config-grid"><div><el-form-item label="当前模型通道" prop="activeProvider"><el-select v-model="config.activeProvider"><el-option value="MOCK_LOCAL" label="本地智能沙箱 · MOCK_LOCAL"/><el-option value="DEEPSEEK" label="DeepSeek"/><el-option value="QWEN" label="通义千问 · Qwen"/></el-select></el-form-item><el-form-item label="API Base URL" prop="baseUrl"><el-input v-model="config.baseUrl" maxlength="255" placeholder="https://api.deepseek.com/v1"/></el-form-item><el-form-item label="模型名称" prop="modelName"><el-input v-model="config.modelName" maxlength="128" placeholder="例如 deepseek-chat"/></el-form-item><el-form-item label="API Key"><el-input v-model="config.apiKeyPlain" type="password" show-password autocomplete="new-password" maxlength="512" :placeholder="config.apiKeyMasked || '未配置，留空使用本地沙箱'"/></el-form-item><el-form-item label="自动降级"><el-switch v-model="config.enableMockFallback" active-text="调用异常时启用本地智能沙箱"/></el-form-item></div><div><el-form-item label="敏感词规则 · 每行一条"><el-input v-model="words" type="textarea" :rows="12" maxlength="20200" placeholder="每行填写一个需要拦截的敏感词或短语"/></el-form-item><p class="muted">规则保存后立即用于请求检查。恶意脚本始终会被拦截。</p><p class="muted">API Key 仅以掩码显示，可输入新 Key 进行替换。</p></div></div><div class="config-footer"><span class="muted">模型配置变更会写入安全审计日志</span><el-button type="primary" native-type="submit" :loading="saving">保存配置</el-button></div></el-form></article><article class="panel list-panel audit-panel"><div class="panel-heading"><div><h2>安全审计日志</h2><p>身份认证、算力变动、模型调用与违规拦截记录</p></div><el-tag type="info" effect="plain">{{ total }} 条记录</el-tag></div><el-form inline class="search-form audit-search" @submit.prevent="loadLogs(true)"><el-form-item label="账号"><el-input v-model="query.username" clearable maxlength="64" placeholder="操作账号"/></el-form-item><el-form-item label="模块"><el-select v-model="query.moduleName" placeholder="全部模块" clearable><el-option v-for="m in modules" :key="m" :value="m" :label="m"/></el-select></el-form-item><el-form-item label="动作"><el-select v-model="query.actionType" placeholder="全部动作" clearable><el-option v-for="a in actions" :key="a" :value="a" :label="a"/></el-select></el-form-item><el-form-item label="模型通道"><el-select v-model="query.modelProvider" placeholder="全部通道" clearable><el-option v-for="p in providers" :key="p" :value="p" :label="p"/></el-select></el-form-item><el-form-item label="HTTP 状态"><el-input-number v-model="query.httpStatus" :min="100" :max="599" :precision="0" :controls="false" placeholder="如 200"/></el-form-item><el-form-item label="时间"><el-date-picker v-model="dates" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" start-placeholder="开始时间" end-placeholder="结束时间"/></el-form-item><el-form-item><el-button type="primary" :icon="Search" native-type="submit">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form><el-alert v-if="failed" title="审计日志加载失败，请重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="暂无符合条件的审计日志"><el-table-column label="时间" min-width="175"><template #default="{ row }">{{ formatTime(row.createdAt) }}</template></el-table-column><el-table-column label="账号" min-width="130"><template #default="{ row }">{{ row.username || '未登录用户' }}</template></el-table-column><el-table-column prop="moduleName" label="模块" width="100"/><el-table-column label="动作" min-width="155"><template #default="{ row }"><el-tag :type="row.actionType === 'SENSITIVE_BLOCK' ? 'danger' : 'info'" effect="plain" size="small">{{ row.actionType }}</el-tag></template></el-table-column><el-table-column label="通道" min-width="120"><template #default="{ row }">{{ row.modelProvider || '—' }}</template></el-table-column><el-table-column label="HTTP" width="80"><template #default="{ row }"><el-text :type="row.httpStatus >= 400 ? 'danger' : 'success'">{{ row.httpStatus }}</el-text></template></el-table-column><el-table-column prop="costTokens" label="Tokens" width="95" align="right"/><el-table-column prop="durationMs" label="耗时 ms" width="95" align="right"/><el-table-column label="操作" width="80" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row)">详情</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{ total }} 条日志</span><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" :page-sizes="[10,20,50]" layout="sizes,prev,pager,next" @size-change="loadLogs(true)" @current-change="loadLogs()"/></div></article><el-drawer v-model="drawer" title="审计事件详情" size="min(620px, 95vw)"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="事件 ID">{{ detail.id }}</el-descriptions-item><el-descriptions-item label="账号">{{ detail.username || '未登录用户' }}</el-descriptions-item><el-descriptions-item label="请求">{{ detail.requestMethod }} {{ detail.requestUri }}</el-descriptions-item><el-descriptions-item label="客户端 IP">{{ detail.requestIp || '—' }}</el-descriptions-item><el-descriptions-item label="发生时间">{{ formatTime(detail.createdAt) }}</el-descriptions-item><el-descriptions-item label="异常信息">{{ detail.errorMsg || '无' }}</el-descriptions-item></el-descriptions><h3 class="detail-title">扩展详情</h3><pre class="audit-detail">{{ JSON.stringify(detail.detailJson, null, 2) || '无扩展详情' }}</pre></template></el-drawer></section></template>
<style scoped>.config-panel{margin-bottom:25px}.config-panel>.el-form{padding:0 25px 22px}.config-panel>.el-alert{margin-bottom:20px}.config-grid{display:grid;grid-template-columns:1fr 1fr;gap:35px}.config-grid .el-select{width:100%}.config-footer{border-top:1px solid #e6ece3;padding-top:20px;display:flex;align-items:center;justify-content:space-between}.audit-search .el-select{width:160px}.audit-search .el-input-number{width:110px}.detail-title{margin:24px 0 12px}.audit-detail{padding:20px;background:#f3f6f1;border:1px solid #e2e9de;border-radius:8px;font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:1000px){.config-grid{grid-template-columns:1fr;gap:10px}}</style>
